={{ (() => {
  const raw = $json.body || $json;
  const clientSlug = (raw.client_name || 'project').toLowerCase().replace(/[^a-z0-9]+/g, '-');
  const date = new Date().toISOString().slice(0, 10);
  const project = raw.project || (clientSlug + '-' + date);
  return JSON.stringify({ project, client_name: raw.client_name, style: raw.style || '' });
})() }}

parameters.jsCode:
let content = $json.choices?.[0]?.message?.content || '';
content = content.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();

let parsed;
try { parsed = JSON.parse(content); }
catch(e) {
  const match = content.match(/\{[\s\S]*\}/);
  if (match) { try { parsed = JSON.parse(match[0]); } catch(e2) { throw new Error('HTML JSON inválido: ' + content.slice(0, 300)); } }
  else { throw new Error('No se encontró JSON en respuesta HTML: ' + content.slice(0, 300)); }
}

const ctx = $('Code - Preparar HTML Prompt').item.json;

const htmlMap = {};
for (const b of (parsed.beats || [])) {
  if (b.id && b.html_content) htmlMap[b.id] = b.html_content;
}

const beats = ctx.beats_plan.map(beat => ({
  ...beat,
  html_content: htmlMap[beat.id] || null
})).filter(b => b.html_content);

if (beats.length === 0) {
  throw new Error('No se generaron HTMLs. Respuesta: ' + content.slice(0, 200));
}

return [{
  json: {
    beats,
    video_w: ctx.video_w,
    video_h: ctx.video_h,
    fps: ctx.fps,
    project: ctx.project
  }
}];

// Detectar si HTTP - Render devolvió error (500 o timeout)
const r = $json;
const hasError = r.ok !== true || r.error !== undefined;
const errorMsg = typeof r.error === 'string'
  ? r.error
  : (r.error?.message || r.message || JSON.stringify(r.error) || 'Error desconocido en render');
return [{ json: { ...r, _has_error: hasError, _error_msg: String(errorMsg).slice(0, 800) } }];

// Construir prompt para que OpenAI diagnostique el error de render
const ctx = $json;
const project = $('Webhook').item.json.body.project;

const systemPrompt = `You are a diagnostic AI for a video rendering pipeline running on Ubuntu 24.04.
The pipeline uses Puppeteer (bundled Chrome), FFmpeg (ProRes 4444), and Node.js.

AVAILABLE FIX ACTIONS — you must return exactly one of these strings (or null):
- "delete_renders" — deletes corrupt .mov overlay files; use when Chrome crashes, ProtocolError, moov atom not found, ENOENT on .mov file
- "kill_ffmpeg" — kills hanging ffmpeg processes; use when timeout / process stuck / ETIMEDOUT
- "reset_project" — full clean of compositions dir; use as last resort for unknown errors
- null — cannot auto-fix; escalate to human

COMMON ERRORS → FIX MAPPINGS:
- "moov atom not found" → delete_renders
- "ProtocolError" / "Target closed" / Chrome crash → delete_renders
- "ETIMEDOUT" / "timeout" / encode hung → kill_ffmpeg (then retry will re-render)
- "ENOENT" → delete_renders
- Unknown → null

Respond ONLY with valid JSON (no markdown):
{"fix_action": "...", "explanation": "..."}`.trim();

const userMessage = `RENDER FAILED\nProject: ${project}\nError: ${ctx._error_msg}`;

return [{ json: {
  system_prompt: systemPrompt,
  user_message: userMessage,
  project,
  error_msg: ctx._error_msg
}}];

// Parsear la respuesta de OpenAI y extraer la acción de reparación
let content = $json.choices?.[0]?.message?.content || '{"fix_action":null,"explanation":"parse error"}';
content = content.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
let parsed;
try { parsed = JSON.parse(content); }
catch(e) { parsed = { fix_action: null, explanation: 'JSON parse error: ' + content.slice(0, 120) }; }

const diagCtx = $('Code - Render Diagnose Prompt').item.json;
return [{ json: {
  fix_action: parsed.fix_action || null,
  explanation: parsed.explanation || '',
  project: diagCtx.project,
  error_msg: diagCtx.error_msg,
  should_fix: !!parsed.fix_action
}}];

const r = $json;
const hasError = r.ok !== true || r.error !== undefined;
const errorMsg = typeof r.error === 'string' ? r.error : (r.error?.message || 'Retry render failed');
const fixCtx = $('Code - Parse Render Fix').item.json;
return [{ json: { ...r, _has_error: hasError, _error_msg: errorMsg, explanation: fixCtx.explanation, project: fixCtx.project }}];
